def count_target_triples(arr, target):
    MOD = 1_000_000_007
    count = Counter(arr)
    values = sorted(count)
    total = 0
    for i, a in enumerate(values):
        for b in values[i:]:
            c = target - a - b
            if c < b or c not in count:
