            if a == b == c:
                total += count[a] * (count[a] - 1) * (count[a] - 2) // 6
            elif a == b:
                total += count[a] * (count[a] - 1) // 2 * count[c]
            elif b == c:
                total += count[a] * count[b] * (count[b] - 1) // 2
            else:
                total += count[a] * count[b] * count[c]
