def all_ancestors(n, edges):
    children = [[] for _ in range(n)]
    for u, v in edges:
        children[u].append(v)
    answer = [[] for _ in range(n)]
    for start in range(n):          # increasing order keeps lists sorted
        seen = {start}
        stack = [start]
        while stack:
            node = stack.pop()
            for nxt in children[node]:
                if nxt not in seen:
                    seen.add(nxt)
                    answer[nxt].append(start)
                    stack.append(nxt)
