from functools import lru_cache


def all_full_trees(n):
    @lru_cache(maxsize=None)
    def build(size):
        if size == 1:
            return [TreeNode(0)]
        trees = []
        for left in range(1, size - 1, 2):
            for l in build(left):
                for r in build(size - 1 - left):
                    trees.append(TreeNode(0, l, r))
        return trees

    def level_order(root):
        out, queue = [], [root]
        for node in queue:
            if node is None:
                out.append(None)
            else:
                out.append(node.val)
                queue.append(node.left)
                queue.append(node.right)
        while out and out[-1] is None:
            out.pop()
        return out

    if n % 2 == 0:
        return []
    return [level_order(t) for t in build(n)]

