    best = 0

    def dfs(node, parent_val, length):
        nonlocal best
        if node is None:
            return
        if parent_val is not None and node.val == parent_val + 1:
            length += 1
        else:
            length = 1
        best = max(best, length)
        dfs(node.left, node.val, length)
        dfs(node.right, node.val, length)

    dfs(root, None, 0)
    return best

def longest_consecutive_path(root):
    best = 0

    def walk(node):
        # returns (longest path going down with +1 steps, longest going down with -1 steps), starting at node
        nonlocal best
        up = down = 1
        for child in (node.left, node.right):
            if child is None:
                continue
            child_up, child_down = walk(child)
            if child.val == node.val + 1:
                up = max(up, child_up + 1)
            elif child.val == node.val - 1:
                down = max(down, child_down + 1)
        best = max(best, up + down - 1)
        return up, down

    if root:
        walk(root)
    return best

