def brace_expansion(expression):
    pos = 0

    def parse_union():
        nonlocal pos
        words = set()
        while True:
            words |= parse_concat()
            if pos < len(expression) and expression[pos] == ",":
                pos += 1
            else:
                return words

    def parse_concat():
        nonlocal pos
        words = {""}
        while pos < len(expression) and expression[pos] not in ",}":
            if expression[pos] == "{":
                pos += 1
                part = parse_union()
                pos += 1  # skip the closing brace
            else:
                part = {expression[pos]}
                pos += 1
            words = {a + b for a in words for b in part}
        return words

    return sorted(parse_union())

