def has_loop(nums):
    nums = nums[:]  # we mark visited indices with 0, so work on a copy
    n = len(nums)

    def step(i):
        return (i + nums[i]) % n

    for start in range(n):
        if nums[start] == 0:
            continue
        forward = nums[start] > 0
        slow = fast = start
        while True:
            # each move must stay in the same direction and not loop on itself
            nxt = step(fast)
            if (nums[nxt] > 0) != forward or nums[nxt] == 0 or nxt == fast:
                break
            fast = nxt
            nxt = step(fast)
            if (nums[nxt] > 0) != forward or nums[nxt] == 0 or nxt == fast:
                break
            fast = nxt
            slow = step(slow)
            if slow == fast:
                return True
        # nothing reachable from start forms a valid loop: mark that path as dead
        i = start
        while nums[i] != 0 and (nums[i] > 0) == forward:
            nxt = step(i)
            nums[i] = 0
            i = nxt
