def min_abs_difference(nums, goal):
    def all_sums(part):
        sums = [0]
        for x in part:
            sums += [s + x for s in sums]
        return sums

    half = len(nums) // 2
    left = all_sums(nums[:half])
    right = sorted(all_sums(nums[half:]))
    best = abs(goal)
    for s in left:
        need = goal - s
        i = bisect_left(right, need)
        # the closest right-half sums sit at i and i - 1
        for j in (i - 1, i):
            if 0 <= j < len(right):
                best = min(best, abs(s + right[j] - goal))
    return best

