def build_tree(inorder, postorder):
    where = {val: i for i, val in enumerate(inorder)}

    def build(in_lo, in_hi, post_lo, post_hi):
        if in_lo > in_hi:
            return None
        root_val = postorder[post_hi]
        mid = where[root_val]
        left_size = mid - in_lo
        root = TreeNode(root_val)
        root.left = build(in_lo, mid - 1, post_lo, post_lo + left_size - 1)
        root.right = build(mid + 1, in_hi, post_lo + left_size, post_hi - 1)
        return root

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

def build_tree(preorder, inorder):
    position = {val: i for i, val in enumerate(inorder)}
    next_root = 0

    def build(lo, hi):
        nonlocal next_root
        if lo > hi:
            return None
        val = preorder[next_root]
        next_root += 1
        mid = position[val]
        node = TreeNode(val)
        node.left = build(lo, mid - 1)
        node.right = build(mid + 1, hi)
        return node

    return build(0, len(inorder) - 1)

def build_from_pre_post(preorder, postorder):
    post_index = {val: i for i, val in enumerate(postorder)}

    def build(pre_lo, pre_hi, post_lo):
        # Builds the subtree whose preorder is preorder[pre_lo..pre_hi]
        # and whose postorder starts at postorder[post_lo].
        if pre_lo > pre_hi:
            return None
        root = TreeNode(preorder[pre_lo])
        if pre_lo == pre_hi:
            return root
        left_val = preorder[pre_lo + 1]
        left_size = post_index[left_val] - post_lo + 1
        root.left = build(pre_lo + 1, pre_lo + left_size, post_lo)
        root.right = build(pre_lo + left_size + 1, pre_hi, post_lo + left_size)
        return root

    return build(0, len(preorder) - 1, 0)

