def repeat_limited_string(s, repeat_limit):
    counts = [0] * 26
    for ch in s:
        counts[ord(ch) - ord("a")] += 1

    pieces = []
    i = 25
    while i >= 0:
        if counts[i] == 0:
            i -= 1
            continue
        use = min(counts[i], repeat_limit)
        pieces.append(chr(ord("a") + i) * use)
        counts[i] -= use
        if counts[i] == 0:
            i -= 1
            continue
        # Still more of letter i: break the run with the next largest letter.
        j = i - 1
        while j >= 0 and counts[j] == 0:
            j -= 1
        if j < 0:
            break
        pieces.append(chr(ord("a") + j))
        counts[j] -= 1
    return "".join(pieces)

