def largest_sequence(n):
    result = [0] * (2 * n - 1)
    used = [False] * (n + 1)

    def place(i):
        while i < len(result) and result[i] != 0:
            i += 1
        if i == len(result):
            return True
        for x in range(n, 0, -1):
            if used[x]:
                continue
            if x == 1:
                result[i] = 1
                used[1] = True
                if place(i + 1):
                    return True
                result[i] = 0
                used[1] = False
            elif i + x < len(result) and result[i + x] == 0:
                result[i] = result[i + x] = x
                used[x] = True
                if place(i + 1):
                    return True
                result[i] = result[i + x] = 0
                used[x] = False
        return False

    place(0)
    return result

