def contain_virus(grid):
    grid = [row[:] for row in grid]   # 1 = active virus, 2 = sealed, 0 = healthy
    rows, cols = len(grid), len(grid[0])
    total_walls = 0

    while True:
        seen = set()
        regions, threats, walls = [], [], []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != 1 or (r, c) in seen:
                    continue
                region, threat, wall = [], set(), 0
                seen.add((r, c))
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    region.append((cr, cc))
                    for nr, nc in ((cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)):
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            continue
                        if grid[nr][nc] == 1 and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
                        elif grid[nr][nc] == 0:
                            threat.add((nr, nc))
                            wall += 1
                regions.append(region)
                threats.append(threat)
                walls.append(wall)

        if not regions:
            break
        worst = max(range(len(regions)), key=lambda i: len(threats[i]))
        if not threats[worst]:
            break
        total_walls += walls[worst]
        for i, region in enumerate(regions):
            if i == worst:
                for r, c in region:
                    grid[r][c] = 2
            else:
                for r, c in threats[i]:
                    grid[r][c] = 1
    return total_walls

