    left_height = right_height = 0
    node = root
    while node:
        left_height += 1
        node = node.left
    node = root
    while node:
        right_height += 1
        node = node.right
    if left_height == right_height:
        return 2 ** left_height - 1
    return 1 + count_nodes(root.left) + count_nodes(root.right)

