def count_range_sums(nums, lower, upper):
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)

    def sort_and_count(lo, hi):  # works on prefix[lo:hi]
        if hi - lo <= 1:
            return 0
        mid = (lo + hi) // 2
        count = sort_and_count(lo, mid) + sort_and_count(mid, hi)
        j = k = mid
        for left in prefix[lo:mid]:
            while j < hi and prefix[j] - left < lower:
                j += 1
            while k < hi and prefix[k] - left <= upper:
                k += 1
            count += k - j
        prefix[lo:hi] = sorted(prefix[lo:hi])
        return count

    return sort_and_count(0, len(prefix))

