def count_sub_islands(grid1, grid2):
    rows, cols = len(grid2), len(grid2[0])
    seen = [[False] * cols for _ in range(rows)]

    def explore(r, c):
        # Visit the whole island; report whether all of it is land in grid1.
        if r < 0 or r >= rows or c < 0 or c >= cols or grid2[r][c] == 0 or seen[r][c]:
            return True
        seen[r][c] = True
        ok = grid1[r][c] == 1
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            if not explore(r + dr, c + dc):
                ok = False  # keep exploring so the island is fully marked
        return ok

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid2[r][c] == 1 and not seen[r][c] and explore(r, c):
                count += 1
    return count

