def is_cousins(root, x, y):
    level = [(root, None)]  # (node, parent) pairs at the current depth
    while level:
        parent_of = {}
        next_level = []
        for node, parent in level:
            if node.val in (x, y):
                parent_of[node.val] = parent
            if node.left:
                next_level.append((node.left, node))
            if node.right:
