def critical_links(n, links):
    graph = [[] for _ in range(n)]
    for a, b in links:
        graph[a].append(b)
        graph[b].append(a)

    order = [-1] * n   # when each node was first visited
    low = [0] * n      # earliest visit time reachable without using the parent edge
    bridges = []
    timer = 0

    def dfs(node, parent):
        nonlocal timer
        order[node] = low[node] = timer
        timer += 1
        for nxt in graph[node]:
            if nxt == parent:
                continue
            if order[nxt] == -1:
                dfs(nxt, node)
                low[node] = min(low[node], low[nxt])
                if low[nxt] > order[node]:
                    bridges.append([node, nxt])
            else:
                low[node] = min(low[node], order[nxt])

    dfs(0, -1)
    return bridges

