from collections import deque


def distance_to_cycle(n, edges):
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    # Peel off leaves again and again; whatever survives is the cycle.
    degree = [len(nbrs) for nbrs in graph]
    on_cycle = [True] * n
    queue = deque(i for i in range(n) if degree[i] == 1)
    while queue:
        node = queue.popleft()
        on_cycle[node] = False
        for nxt in graph[node]:
            degree[nxt] -= 1
            if degree[nxt] == 1:
                queue.append(nxt)

    # Multi-source BFS outward from every cycle node.
    answer = [-1] * n
    queue = deque()
    for i in range(n):
        if on_cycle[i]:
            answer[i] = 0
            queue.append(i)
    while queue:
        node = queue.popleft()
        for nxt in graph[node]:
            if answer[nxt] == -1:
                answer[nxt] = answer[node] + 1
                queue.append(nxt)
    return answer

