def distribute_elements(nums):
    # Fenwick trees over the ranks of the values answer "how many are > x" in O(log n).
    ranks = {v: i + 1 for i, v in enumerate(sorted(set(nums)))}
    size = len(ranks)

    def add(tree, i):
        while i <= size:
            tree[i] += 1
            i += i & -i

    def count_at_most(tree, i):
        total = 0
        while i > 0:
            total += tree[i]
            i -= i & -i
        return total

    first, second = [nums[0]], [nums[1]]
    tree1, tree2 = [0] * (size + 1), [0] * (size + 1)
    add(tree1, ranks[nums[0]])
    add(tree2, ranks[nums[1]])
    for x in nums[2:]:
        r = ranks[x]
        g1 = len(first) - count_at_most(tree1, r)
        g2 = len(second) - count_at_most(tree2, r)
        if g1 > g2 or (g1 == g2 and len(first) <= len(second)):
            first.append(x)
            add(tree1, r)
        else:
            second.append(x)
            add(tree2, r)
    return first + second

