def fence_points(trees):
    pts = sorted(map(tuple, trees))
    if len(pts) <= 2:
        return [list(p) for p in pts]

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def half(points):
        chain = []
        for p in points:
            # pop only on a strict right turn so collinear points stay
            while len(chain) >= 2 and cross(chain[-2], chain[-1], p) < 0:
                chain.pop()
            chain.append(p)
        return chain

    hull = set(half(pts)) | set(half(pts[::-1]))
    return [list(p) for p in sorted(hull)]

