from collections import deque

def maximum_minutes(grid):
    rows, cols = len(grid), len(grid[0])
    INF = float("inf")
    steps = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def neighbours(r, c):
        for dr, dc in steps:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                yield nr, nc

    # minute at which the fire reaches each cell
    fire = [[INF] * cols for _ in range(rows)]
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                fire[r][c] = 0
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in neighbours(r, c):
            if fire[nr][nc] == INF:
                fire[nr][nc] = fire[r][c] + 1
                queue.append((nr, nc))

    goal = (rows - 1, cols - 1)

    def can_escape(wait):
        if fire[0][0] <= wait:
            return False
        seen = {(0, 0)}
        queue = deque([(0, 0, wait)])
        while queue:
            r, c, t = queue.popleft()
            for nr, nc in neighbours(r, c):
                if (nr, nc) in seen:
                    continue
                if (nr, nc) == goal:
                    if t + 1 <= fire[nr][nc]:
                        return True
                elif t + 1 < fire[nr][nc]:
                    seen.add((nr, nc))
                    queue.append((nr, nc, t + 1))
        return False

    low, high = -1, rows * cols         # can_escape(low) holds (or low is -1); find the largest
    if can_escape(high):
        return 1000000000
    while low < high - 1:
        mid = (low + high) // 2
        if can_escape(mid):
            low = mid
        else:
            high = mid
    return low

