def exclusive_time(n, logs):
    totals = [0] * n
    stack = []
    prev = 0
    for entry in logs:
        fid, kind, t = entry.split(":")
        fid, t = int(fid), int(t)
        if kind == "start":
            if stack:
                totals[stack[-1]] += t - prev
            stack.append(fid)
            prev = t
        else:
            totals[stack.pop()] += t - prev + 1
            prev = t + 1
    return totals

