def add_operators(digits, target):
    results = []

    def build(pos, expr, value, last):
        if pos == len(digits):
            if value == target:
                results.append(expr)
            return
        for end in range(pos + 1, len(digits) + 1):
            piece = digits[pos:end]
            if len(piece) > 1 and piece[0] == "0":
                break
            num = int(piece)
            if pos == 0:
                build(end, piece, num, num)
            else:
                build(end, expr + "+" + piece, value + num, num)
                build(end, expr + "-" + piece, value - num, -num)
                # undo the last term, then multiply it in
                build(end, expr + "*" + piece, value - last + last * num, last * num)

    build(0, "", 0, 0)
    return results

