from collections import deque


def safe_walk(grid, health):
    rows, cols = len(grid), len(grid[0])
    INF = float("inf")
    cost = [[INF] * cols for _ in range(rows)]
    cost[0][0] = grid[0][0]
    dq = deque([(0, 0)])
    while dq:  # 0-1 BFS: cheapest number of 1-cells to reach each cell
        r, c = dq.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                new_cost = cost[r][c] + grid[nr][nc]
                if new_cost < cost[nr][nc]:
                    cost[nr][nc] = new_cost
                    if grid[nr][nc] == 0:
                        dq.appendleft((nr, nc))
                    else:
                        dq.append((nr, nc))
    return health - cost[rows - 1][cols - 1] >= 1

