def number_of_stable_arrays(zero, one, limit):
    MOD = 1_000_000_007
    # end0[i][j] / end1[i][j]: stable lists with i zeros and j ones that end in a 0 / a 1
    end0 = [[0] * (one + 1) for _ in range(zero + 1)]
    end1 = [[0] * (one + 1) for _ in range(zero + 1)]
    for i in range(zero + 1):
        for j in range(one + 1):
            # the list ends with a run of `run` zeros, preceded by nothing or by a 1
            for run in range(1, min(limit, i) + 1):
                end0[i][j] += 1 if (i == run and j == 0) else end1[i - run][j]
            for run in range(1, min(limit, j) + 1):
                end1[i][j] += 1 if (j == run and i == 0) else end0[i][j - run]
            end0[i][j] %= MOD
            end1[i][j] %= MOD
    return (end0[zero][one] + end1[zero][one]) % MOD

