def find_mst_edges(n, edges):
    order = sorted(range(len(edges)), key=lambda i: edges[i][2])

    def mst_weight(skip=-1, force=-1):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        total, used = 0, 0
        if force != -1:
            a, b, w = edges[force]
            parent[find(a)] = find(b)
            total, used = w, 1
        for i in order:
            if i == skip:
                continue
            a, b, w = edges[i]
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                total += w
                used += 1
        return total if used == n - 1 else float("inf")

    best = mst_weight()
    critical, pseudo = [], []
    for i in range(len(edges)):
        if mst_weight(skip=i) > best:
            critical.append(i)
        elif mst_weight(force=i) == best:
            pseudo.append(i)
    return [critical, pseudo]

