import heapq


def shortest_path_edges(n, edges):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dijkstra(src):
        dist = [float("inf")] * n
        dist[src] = 0
        heap = [(0, src)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(heap, (d + w, v))
        return dist

    from_start, from_end = dijkstra(0), dijkstra(n - 1)
    best = from_start[n - 1]
    if best == float("inf"):
        return [False] * len(edges)
    return [from_start[u] + w + from_end[v] == best or from_start[v] + w + from_end[u] == best
            for u, v, w in edges]

