def kth_pair_distance(nums, k):
    nums = sorted(nums)

    def pairs_within(d):
        # number of pairs with distance <= d, using a sliding left pointer
        count = left = 0
        for right in range(len(nums)):
            while nums[right] - nums[left] > d:
                left += 1
            count += right - left
        return count

    lo, hi = 0, nums[-1] - nums[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if pairs_within(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

