def find_kth_bit(n, k):
    if n == 1:
        return "0"
    middle = 1 << (n - 1)               # Sn has length 2**n - 1; the "1" sits in the middle
    if k == middle:
        return "1"
    if k < middle:
        return find_kth_bit(n - 1, k)
    mirrored = find_kth_bit(n - 1, (1 << n) - k)
    return "1" if mirrored == "0" else "0"

