from collections import deque


def min_merged_diameter(edges1, edges2):
    def farthest(graph, start):
        dist = {start: 0}
        queue = deque([start])
        last = start
        while queue:
            node = queue.popleft()
            last = node
            for nxt in graph[node]:
                if nxt not in dist:
                    dist[nxt] = dist[node] + 1
                    queue.append(nxt)
        return last, dist[last]

    def diameter(edges):
        graph = [[] for _ in range(len(edges) + 1)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        end, _ = farthest(graph, 0)
        _, length = farthest(graph, end)
        return length

    d1, d2 = diameter(edges1), diameter(edges2)
    # Joining the two centers: each side contributes its radius, ceil(d / 2).
    through = (d1 + 1) // 2 + (d2 + 1) // 2 + 1
    return max(d1, d2, through)

