def nearest_palindrome(n):
    length = len(n)
    value = int(n)
    candidates = {10 ** (length - 1) - 1, 10 ** length + 1}  # e.g. 99 and 1001
    prefix = int(n[:(length + 1) // 2])
    for p in (prefix - 1, prefix, prefix + 1):
        left = str(p)
        if length % 2 == 0:
            mirrored = left + left[::-1]
        else:
            mirrored = left + left[:-1][::-1]
        candidates.add(int(mirrored))
    candidates.discard(value)
    best = min(candidates, key=lambda c: (abs(c - value), c))
    return str(best)

