def min_total_area(grid):
    rows, cols = len(grid), len(grid[0])

    def box(r1, r2, c1, c2):
        # area of the tightest rectangle around the 1s in rows r1..r2-1, columns c1..c2-1
        top, bottom, left, right = rows, -1, cols, -1
        for r in range(r1, r2):
            for c in range(c1, c2):
                if grid[r][c] == 1:
                    top, bottom = min(top, r), max(bottom, r)
                    left, right = min(left, c), max(right, c)
        return 0 if bottom == -1 else (bottom - top + 1) * (right - left + 1)

    best = rows * cols
    for a in range(1, rows):                      # three horizontal bands
        for b in range(a + 1, rows):
            best = min(best, box(0, a, 0, cols) + box(a, b, 0, cols) + box(b, rows, 0, cols))
    for a in range(1, cols):                      # three vertical bands
        for b in range(a + 1, cols):
