from math import gcd

def equal_gcd_pairs(nums):
    MOD = 1_000_000_007
    # ways[(g1, g2)] = number of ways so far where A has gcd g1 and B has gcd g2 (0 means still empty)
    ways = {(0, 0): 1}
    for x in nums:
        nxt = dict(ways)                        # x goes in neither
        for (g1, g2), count in ways.items():
            for key in ((gcd(g1, x), g2), (g1, gcd(g2, x))):   # x goes in A, or in B
                nxt[key] = (nxt.get(key, 0) + count) % MOD
        ways = nxt
    return sum(c for (g1, g2), c in ways.items() if g1 == g2 and g1 > 0) % MOD

