import heapq
from collections import deque


def safest_path(grid):
    n = len(grid)
    dist = [[-1] * n for _ in range(n)]
    queue = deque()
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                dist[r][c] = 0
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < n and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                queue.append((nr, nc))

    heap = [(-dist[0][0], 0, 0)]
    visited = [[False] * n for _ in range(n)]
    while heap:
        neg_safe, r, c = heapq.heappop(heap)
        if visited[r][c]:
            continue
        visited[r][c] = True
        if (r, c) == (n - 1, n - 1):
            return -neg_safe
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                heapq.heappush(heap, (-min(-neg_safe, dist[nr][nc]), nr, nc))
    return 0

