def min_moves(matrix):
    m, n = len(matrix), len(matrix[0])
    portals = {}
    for r in range(m):
        for c in range(n):
            ch = matrix[r][c]
            if ch.isupper():
                portals.setdefault(ch, []).append((r, c))
    INF = float("inf")
