def money_needed(n):
    @lru_cache(maxsize=None)
    def cost(lo, hi):
        if lo >= hi:
            return 0
        best = float("inf")
        for guess in range(lo, hi + 1):
            worst = guess + max(cost(lo, guess - 1), cost(guess + 1, hi))
            best = min(best, worst)
        return best

