from collections import Counter

def can_split_runs(hand, size):
    if len(hand) % size:
        return False
    count = Counter(hand)
    for start in sorted(count):
        need = count[start]
        if need == 0:
            continue
        # the smallest remaining card must start a run
        for v in range(start, start + size):
            if count[v] < need:
                return False
            count[v] -= need
    return True

