        count, i = 0, 0
        while i < len(nums):
            if nums[i] <= cap:
                count += 1
                i += 2
            else:
                i += 1
        return count >= k

    lo, hi = min(nums), max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_rob(mid):
            hi = mid
        else:
