def k_inverse_pairs(n, k):
    MOD = 1_000_000_007
    dp = [1] + [0] * k  # dp[j]: orderings of the numbers so far with j inverse pairs
    for size in range(2, n + 1):
        new = [0] * (k + 1)
        running = 0
        for j in range(k + 1):
            running += dp[j]
            if j - size >= 0:
                running -= dp[j - size]
            new[j] = running % MOD
        dp = new
