from functools import lru_cache

def longest_v_segment(grid):
    rows, cols = len(grid), len(grid[0])
    # diagonal directions in clockwise order
    dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

    @lru_cache(maxsize=None)
    def extend(r, c, d, can_turn, want):
        # cells we can add starting at (r, c), which must hold `want`
        if not (0 <= r < rows and 0 <= c < cols) or grid[r][c] != want:
            return 0
        nxt = 0 if want == 2 else 2
        dr, dc = dirs[d]
        best = extend(r + dr, c + dc, d, can_turn, nxt)
        if can_turn:
            nd = (d + 1) % 4
            best = max(best, extend(r + dirs[nd][0], c + dirs[nd][1], nd, False, nxt))
        return 1 + best

    best = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                for d, (dr, dc) in enumerate(dirs):
                    best = max(best, 1 + extend(r + dr, c + dc, d, True, 2))
    return best

