    def find(ch):
        while parent[ch] != ch:
            parent[ch] = parent[parent[ch]]
            ch = parent[ch]
        return ch

    for a, b in zip(s1, s2):
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the smaller letter as the group's representative
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb
    return "".join(find(ch) for ch in base_str)

