def generate_string(str1, str2):
    n, m = len(str1), len(str2)
    word = [None] * (n + m - 1)
    for i, rule in enumerate(str1):
        if rule == "T":
            for j, ch in enumerate(str2):
                if word[i + j] is not None and word[i + j] != ch:
                    return ""  # two T windows disagree
                word[i + j] = ch
    fixed = [ch is not None for ch in word]
    word = [ch if ch is not None else "a" for ch in word]
    for i, rule in enumerate(str1):
        if rule == "F" and "".join(word[i:i + m]) == str2:
            # break the match as late (and as cheaply) as possible
            for j in range(i + m - 1, i - 1, -1):
                if not fixed[j]:
                    word[j] = "b"
                    break
            else:
                return ""
    return "".join(word)

