def longest_happy_length(a, b, c):
    heap = [(-count, ch) for count, ch in ((a, "a"), (b, "b"), (c, "c")) if count > 0]
    heapq.heapify(heap)
    built = []
    while heap:
        count, ch = heapq.heappop(heap)
        if len(built) >= 2 and built[-1] == built[-2] == ch:
            if not heap:
                break
            count2, ch2 = heapq.heappop(heap)
            built.append(ch2)
            if count2 + 1 < 0:
                heapq.heappush(heap, (count2 + 1, ch2))
            heapq.heappush(heap, (count, ch))
        else:
            built.append(ch)
            if count + 1 < 0:
                heapq.heappush(heap, (count + 1, ch))
    return len(built)

