def longest_k_repeating(s, k):
    if len(s) < k:
        return 0
    counts = Counter(s)
    for i, ch in enumerate(s):
        if counts[ch] < k:
            # ch can never be in a valid piece, so split around it
            return max(longest_k_repeating(s[:i], k), longest_k_repeating(s[i + 1:], k))
    return len(s)

