def quietest_richer(richer, quiet):
    n = len(quiet)
    richer_than = [[] for _ in range(n)]
    for a, b in richer:
        richer_than[b].append(a)
    answer = [-1] * n

    def solve(x):
        if answer[x] == -1:
            answer[x] = x
            for r in richer_than[x]:
                candidate = solve(r)
                if quiet[candidate] < quiet[answer[x]]:
                    answer[x] = candidate
        return answer[x]

    for x in range(n):
        solve(x)
    return answer

