    found = 0

    def dfs(node):
        nonlocal found
        if node is None:
            return None
        left = dfs(node.left)
        right = dfs(node.right)
        if node.val == p or node.val == q:
            found += 1
            return node
        if left and right:
            return node
        return left or right

    answer = dfs(root)
    return answer.val if found == 2 else None

