def max_min_gap(spots, m):
    spots = sorted(spots)

    def fits(gap):
        count, last = 1, spots[0]
        for p in spots[1:]:
            if p - last >= gap:
                count += 1
                last = p
        return count >= m

    lo, hi = 1, spots[-1] - spots[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if fits(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

