def shortest_removal(nums, p):
    target = sum(nums) % p
    if target == 0:
        return 0
    last_seen = {0: -1}
    prefix = 0
    best = len(nums)
    for i, x in enumerate(nums):
        prefix = (prefix + x) % p
        need = (prefix - target) % p
        if need in last_seen:
            best = min(best, i - last_seen[need])
        last_seen[prefix] = i
    return best if best < len(nums) else -1

