def largest_island(grid):
    n = len(grid)
    label = [[0] * n for _ in range(n)]
    sizes = {}
    next_id = 1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1 and label[r][c] == 0:
                stack = [(r, c)]
                label[r][c] = next_id
                size = 0
                while stack:
                    i, j = stack.pop()
                    size += 1
                    for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                        if 0 <= a < n and 0 <= b < n and grid[a][b] == 1 and label[a][b] == 0:
                            label[a][b] = next_id
                            stack.append((a, b))
                sizes[next_id] = size
                next_id += 1
    best = max(sizes.values(), default=0)
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                touching = set()
                for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= a < n and 0 <= b < n and label[a][b]:
                        touching.add(label[a][b])
                best = max(best, 1 + sum(sizes[t] for t in touching))
    return best

