def can_form_square(sticks):
    total = sum(sticks)
    if len(sticks) < 4 or total % 4:
        return False
    side = total // 4
    sticks = sorted(sticks, reverse=True)
    if sticks[0] > side:
        return False
    sides = [0] * 4

    def place(i):
        if i == len(sticks):
            return True
        for s in range(4):
            if sides[s] + sticks[i] <= side:
                sides[s] += sticks[i]
                if place(i + 1):
                    return True
                sides[s] -= sticks[i]
            if sides[s] == 0:
                break  # empty sides are interchangeable
        return False

    return place(0)

