def block_sum(mat, k):
    rows, cols = len(mat), len(mat[0])
    pre = [[0] * (cols + 1) for _ in range(rows + 1)]
    for r in range(rows):
        for c in range(cols):
            pre[r + 1][c + 1] = mat[r][c] + pre[r][c + 1] + pre[r + 1][c] - pre[r][c]
    result = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            r1, c1 = max(0, r - k), max(0, c - k)
            r2, c2 = min(rows, r + k + 1), min(cols, c + k + 1)
            result[r][c] = pre[r2][c2] - pre[r1][c2] - pre[r2][c1] + pre[r1][c1]
    return result

