def max_digit_swap_difference(num):
    s = str(num)
    # largest: turn the first non-9 digit into 9 everywhere
    high = s
    for d in s:
        if d != "9":
            high = s.replace(d, "9")
            break
    # smallest: first digit -> 1 if it isn't 1, otherwise first later digit not 0/1 -> 0
    low = s
    if s[0] != "1":
        low = s.replace(s[0], "1")
    else:
        for d in s[1:]:
            if d not in "01":
                low = s.replace(d, "0")
                break
    return int(high) - int(low)

