from bisect import bisect_left, insort


def max_sum_at_most_k(matrix, k):
    rows, cols = len(matrix), len(matrix[0])
    best = None
    for top in range(rows):
        col_sums = [0] * cols
        for bottom in range(top, rows):
            for c in range(cols):
                col_sums[c] += matrix[bottom][c]
            # best subarray sum of col_sums that is <= k
            seen = [0]
            prefix = 0
            for value in col_sums:
                prefix += value
                i = bisect_left(seen, prefix - k)
                if i < len(seen):
                    candidate = prefix - seen[i]
                    if best is None or candidate > best:
                        best = candidate
                insort(seen, prefix)
    return best

