def max_stability(n, edges, k):
    def find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(parent, a, b):
        ra, rb = find(parent, a), find(parent, b)
        if ra == rb:
            return False
        parent[ra] = rb
        return True

    # Required edges must not form a loop; check that once.
    parent = list(range(n))
    for u, v, s, must in edges:
        if must and not union(parent, u, v):
            return -1

    def can_reach(target):
        parent = list(range(n))
        pieces = n
        for u, v, s, must in edges:
            if must:
                if s < target:
                    return False
                union(parent, u, v)
                pieces -= 1
        for u, v, s, must in edges:
            if not must and s >= target and union(parent, u, v):
                pieces -= 1
        upgrades = 0
        for u, v, s, must in edges:
            if not must and 2 * s >= target and union(parent, u, v):
                pieces -= 1
                upgrades += 1
        return pieces == 1 and upgrades <= k

    lo, hi = 1, 2 * max(s for _, _, s, _ in edges) if edges else 0
    best = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_reach(mid):
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return best

