def max_num_of_substrings(s):
    first, last = {}, {}
    for i, ch in enumerate(s):
        first.setdefault(ch, i)
        last[ch] = i

    def closed_end(start):
        # Smallest end so the piece s[start..end] holds every copy of its letters, or -1 if impossible.
        end = last[s[start]]
        j = start
        while j <= end:
            if first[s[j]] < start:
                return -1
            end = max(end, last[s[j]])
            j += 1
        return end

    result = []
    prev_end = -1
    for i, ch in enumerate(s):
        if i != first[ch]:
            continue
        end = closed_end(i)
        if end == -1:
            continue
        if i > prev_end:
            result.append(s[i:end + 1])
        else:
            result[-1] = s[i:end + 1]  # nested inside the previous one, and shorter
        prev_end = end
    return result

