from collections import deque


def max_task_assign(tasks, workers, pills, strength):
    tasks = sorted(tasks)
    workers = sorted(workers)

    def can_do(k):
        # the k easiest tasks, the k strongest workers
        chosen = workers[len(workers) - k:]
        reachable = deque()
        t = 0
        pills_left = pills
        for w in chosen:
            while t < k and tasks[t] <= w + strength:
                reachable.append(tasks[t])
                t += 1
            if not reachable:
                return False
            if reachable[0] <= w:
                reachable.popleft()  # no pill needed: do the easiest task
            elif pills_left > 0:
                reachable.pop()  # with a pill: do the hardest task within reach
                pills_left -= 1
            else:
                return False
        return True

    lo, hi = 0, min(len(tasks), len(workers))
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_do(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

