def max_path_quality(values, edges, max_time):
    adj = [[] for _ in values]
    for u, v, t in edges:
        adj[u].append((v, t))
        adj[v].append((u, t))
    visits = [0] * len(values)
    best = 0

    def walk(node, time_left, quality):
        nonlocal best
        if node == 0:
            best = max(best, quality)
        for nxt, t in adj[node]:
