                gain = values[nxt] if visits[nxt] == 0 else 0
                visits[nxt] += 1
                walk(nxt, time_left - t, quality + gain)
                visits[nxt] -= 1

    visits[0] = 1
    walk(0, max_time, values[0])
    return best

