def maximum_score(grid):
    n = len(grid)
    if n == 1:
        return 0
    # prefix[j][r] = sum of column j over rows 0 .. r - 1
    prefix = [[0] * (n + 1) for _ in range(n)]
    for j in range(n):
        for r in range(n):
            prefix[j][r + 1] = prefix[j][r] + grid[r][j]

    def gain(j, own, reach):
        # Column j is black for rows < own; neighbours reach down to row reach - 1.
        return prefix[j][reach] - prefix[j][own] if reach > own else 0

    heights = range(n + 1)
    # dp[(a, b)]: best score of columns before j, where column j - 1 has height a and column j height b.
    dp = {(0, b): 0 for b in heights}
    for j in range(n - 1):
        new = {}
        for (a, b), score in dp.items():
            for c in heights:
                value = score + gain(j, b, max(a, c))
                if value > new.get((b, c), -1):
                    new[(b, c)] = value
        dp = new
    return max(score + gain(n - 1, b, a) for (a, b), score in dp.items())

