def three_windows(nums, k):
    n = len(nums)
    sums = [sum(nums[:k])]
    for i in range(k, n):
        sums.append(sums[-1] + nums[i] - nums[i - k])
    m = len(sums)

    left = [0] * m  # left[i] = best start in sums[0..i], earliest on ties
    for i in range(1, m):
        left[i] = i if sums[i] > sums[left[i - 1]] else left[i - 1]
    right = [m - 1] * m  # right[i] = best start in sums[i..], earliest on ties
    for i in range(m - 2, -1, -1):
        right[i] = i if sums[i] >= sums[right[i + 1]] else right[i + 1]

    best = None
    for mid in range(k, m - k):
        a, c = left[mid - k], right[mid + k]
        total = sums[a] + sums[mid] + sums[c]
        if best is None or total > best[0]:
            best = (total, [a, mid, c])
    return best[1]

