def max_sum_two_no_overlap(nums, first_len, second_len):
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)

    def window(end, length):  # sum of the window ending just before index end
        return prefix[end] - prefix[end - length]

    def best_order(a, b):
        # a-length window to the left of a b-length window
        best = 0
        best_left = 0
        for end in range(a + b, len(nums) + 1):
            best_left = max(best_left, window(end - b, a))
            best = max(best, best_left + window(end, b))
        return best

    return max(best_order(first_len, second_len), best_order(second_len, first_len))

