def max_tastiness(price, k):
    price = sorted(price)

    def fits(gap):
        count, last = 1, price[0]
        for p in price[1:]:
            if p - last >= gap:
                count += 1
                last = p
        return count >= k

    lo, hi = 0, price[-1] - price[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if fits(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

