def max_value(n, index, max_sum):
    def side_sum(peak, length):
        # values peak-1, peak-2, ... over `length` cells, never below 1
        if length == 0:
            return 0
        if peak - 1 >= length:
            low = peak - length
            return (peak - 1 + low) * length // 2
        ones = length - (peak - 1)
        return (peak - 1) * peak // 2 + ones

    def total(peak):
        return peak + side_sum(peak, index) + side_sum(peak, n - 1 - index)

    lo, hi = 1, max_sum
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if total(mid) <= max_sum:
            lo = mid
        else:
            hi = mid - 1
    return lo

