def max_xor_product(a, b, n):
    MOD = 10**9 + 7
    for i in range(n - 1, -1, -1):
        bit = 1 << i
        if (a & bit) == (b & bit):
            a |= bit
            b |= bit
        elif a < b:
            a |= bit
            b &= ~bit
        else:
            b |= bit
            a &= ~bit
    return (a % MOD) * (b % MOD) % MOD

