from collections import Counter


def can_merge(trees):
    def build(values):
        root = TreeNode(values[0])
        if len(values) > 1 and values[1] is not None:
            root.left = TreeNode(values[1])
        if len(values) > 2 and values[2] is not None:
            root.right = TreeNode(values[2])
        return root

    roots = {}
    leaf_count = Counter()
    for values in trees:
        node = build(values)
        roots[node.val] = node
        for child in (node.left, node.right):
            if child:
                leaf_count[child.val] += 1

    # The final root must be a root that never appears as anyone's leaf.
    starts = [v for v in roots if leaf_count[v] == 0]
    if len(starts) != 1:
        return None
    top = roots.pop(starts[0])

    def attach_and_check(node, low, high):
        if node is None:
            return True
        if not low < node.val < high:
            return False
        if node.left is None and node.right is None and node.val in roots:
            other = roots.pop(node.val)
            node.left, node.right = other.left, other.right
        return (attach_and_check(node.left, low, node.val)
                and attach_and_check(node.right, node.val, high))

    if attach_and_check(top, float("-inf"), float("inf")) and not roots:
        return top
    return None

