def best_node_to_clean(graph, initial):
    n = len(graph)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i in range(n):
        for j in range(i + 1, n):
            if graph[i][j]:
                parent[find(i)] = find(j)

    size = {}
    infected_in = {}
    for i in range(n):
        root = find(i)
        size[root] = size.get(root, 0) + 1
    for node in initial:
        root = find(node)
        infected_in[root] = infected_in.get(root, 0) + 1

    best_node, best_saved = min(initial), -1
    for node in sorted(initial):
        root = find(node)
        # Only a component with a single infected computer can be saved.
        saved = size[root] if infected_in[root] == 1 else 0
        if saved > best_saved:
            best_node, best_saved = node, saved
    return best_node

