        # (cost of halves used, cost of subtracts used, new value)
        yield 0, 0, x
        yield 1, 0, (x + 1) // 2
        if x >= k:
            yield 0, 1, x - k
            yield 1, 1, (x - k + 1) // 2  # subtract, then halve
        if (x + 1) // 2 >= k:
            yield 1, 1, (x + 1) // 2 - k  # halve, then subtract

    @lru_cache(maxsize=None)
    def best(i, a, b):
        if i == len(nums):
            return 0
        result = float("inf")
        for da, db, value in options(nums[i]):
            if da <= a and db <= b:
                result = min(result, value + best(i + 1, a - da, b - db))
        return result

    return best(0, op1, op2)

