import heapq


def min_cost_with_reversals(n, edges):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))      # normal direction
        graph[v].append((u, 2 * w))  # flipped with v's switch
    dist = [float("inf")] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        cost, node = heapq.heappop(heap)
        if cost > dist[node]:
            continue
        if node == n - 1:
            return cost
        for nxt, w in graph[node]:
            if cost + w < dist[nxt]:
                dist[nxt] = cost + w
                heapq.heappush(heap, (cost + w, nxt))
    return -1

