def min_convert_cost(source, target, original, changed, cost):
    INF = float("inf")
    # cheapest cost to turn one string into another, grouped by length
    dist = {}
    for a, b, c in zip(original, changed, cost):
        for s in (a, b):
            dist.setdefault(s, {s: 0})
        dist[a][b] = min(dist[a].get(b, INF), c)
    by_len = {}
    for s in dist:
        by_len.setdefault(len(s), []).append(s)
    for group in by_len.values():
        for mid in group:
            for a in group:
                if dist[a].get(mid, INF) == INF:
                    continue
                for b in group:
                    through = dist[a][mid] + dist[mid].get(b, INF)
                    if through < dist[a].get(b, INF):
                        dist[a][b] = through

    n = len(source)
    best = [INF] * (n + 1)  # best[i]: cost to fix source[:i]
    best[0] = 0
    for i in range(n):
        if best[i] == INF:
