        if source[i] == target[i]:
            best[i + 1] = min(best[i + 1], best[i])
        for length in by_len:
            j = i + length
            if j > n:
                continue
            step = dist.get(source[i:j], {}).get(target[i:j], INF)
            best[j] = min(best[j], best[i] + step)
    return best[n] if best[n] < INF else -1

