import heapq


def min_trip_cost(max_time, edges, fees):
    n = len(fees)
    graph = [[] for _ in range(n)]
    for u, v, t in edges:
        graph[u].append((v, t))
        graph[v].append((u, t))
    fastest = [float("inf")] * n   # quickest arrival seen among cheaper states
    heap = [(fees[0], 0, 0)]        # (fee so far, time so far, city)
    while heap:
        cost, time, city = heapq.heappop(heap)
        if city == n - 1:
            return cost
        if time >= fastest[city]:
            continue   # an earlier pop was cheaper and at least as fast
        fastest[city] = time
        for nxt, t in graph[city]:
            if time + t <= max_time:
                heapq.heappush(heap, (cost + fees[nxt], time + t, nxt))
    return -1

