from collections import deque


def min_cleaning_moves(classroom, energy):
    rows, cols = len(classroom), len(classroom[0])
    litter = {}
    for r in range(rows):
        for c in range(cols):
            if classroom[r][c] == "S":
                start = (r, c)
            elif classroom[r][c] == "L":
                litter[(r, c)] = len(litter)
    full = (1 << len(litter)) - 1
    if full == 0:
        return 0
    best = {(start[0], start[1], 0): energy}  # most energy seen for each state
    queue = deque([(start[0], start[1], 0, energy, 0)])
    while queue:
        r, c, mask, e, moves = queue.popleft()
        if e == 0:
            continue
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or classroom[nr][nc] == "X":
                continue
            ne = energy if classroom[nr][nc] == "R" else e - 1
            nmask = mask | (1 << litter[(nr, nc)]) if (nr, nc) in litter else mask
            if nmask == full:
                return moves + 1
            key = (nr, nc, nmask)
            if best.get(key, -1) < ne:
                best[key] = ne
                queue.append((nr, nc, nmask, ne, moves + 1))
    return -1

