def spread_stones(grid):
    extras = []
    empties = []
    for r in range(3):
        for c in range(3):
            if grid[r][c] == 0:
                empties.append((r, c))
            for _ in range(grid[r][c] - 1):
                extras.append((r, c))
    best = float("inf")
    used = [False] * len(extras)

    def assign(i, cost):
        nonlocal best
        if cost >= best:
            return
        if i == len(empties):
            best = cost
            return
        er, ec = empties[i]
        for j, (sr, sc) in enumerate(extras):
            if not used[j]:
                used[j] = True
                assign(i + 1, cost + abs(sr - er) + abs(sc - ec))
                used[j] = False

    assign(0, 0)
    return best

