import heapq

def min_time_to_corner(grid):
    rows, cols = len(grid), len(grid[0])
    if grid[0][1] > 1 and grid[1][0] > 1:
        return -1                      # stuck: no first move is possible
    best = [[float("inf")] * cols for _ in range(rows)]
    best[0][0] = 0
    heap = [(0, 0, 0)]
    while heap:
        t, r, c = heapq.heappop(heap)
        if (r, c) == (rows - 1, cols - 1):
            return t
        if t > best[r][c]:
            continue
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                arrive = t + 1
                if arrive < grid[nr][nc]:
                    # step back and forth to wait; that keeps the parity of the time
                    wait = grid[nr][nc] - arrive
                    arrive = grid[nr][nc] + wait % 2
                if arrive < best[nr][nc]:
                    best[nr][nc] = arrive
                    heapq.heappush(heap, (arrive, nr, nc))
    return -1

