def most_profitable_path(edges, bob, amount):
    n = len(amount)
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    parent = [-1] * n
    depth = [0] * n
    order = [0]
    seen = [False] * n
    seen[0] = True
    for node in order:
        for nxt in graph[node]:
            if not seen[nxt]:
                seen[nxt] = True
                parent[nxt] = node
                depth[nxt] = depth[node] + 1
                order.append(nxt)

    bob_time = [n] * n          # n means Bob never arrives
    node, t = bob, 0
    while node != -1:
        bob_time[node] = t
        node = parent[node]
        t += 1

    best = None
    income = [0] * n
    for node in order:
        d = depth[node]
        if d < bob_time[node]:
            gain = amount[node]
        elif d == bob_time[node]:
