def count_good_paths(vals, edges):
    n = len(vals)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # add nodes value by value; components only ever contain values <= the current one
    total = 0
    order = sorted(range(n), key=lambda i: vals[i])
    i = 0
    while i < n:
        j = i
        while j < n and vals[order[j]] == vals[order[i]]:
            j += 1
        group = order[i:j]
        for node in group:
            for nb in adj[node]:
                if vals[nb] <= vals[node]:
                    parent[find(nb)] = find(node)
        per_component = {}
        for node in group:
            root = find(node)
            per_component[root] = per_component.get(root, 0) + 1
        for k in per_component.values():
            total += k * (k + 1) // 2           # k single nodes + k*(k-1)/2 paths
        i = j
    return total

