from collections import deque

def ways_odd_deepest_path(edges):
    MOD = 10**9 + 7
    n = len(edges) + 1
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    depth = [-1] * (n + 1)
    depth[1] = 0
    queue = deque([1])
    while queue:
        node = queue.popleft()
        for nxt in adj[node]:
            if depth[nxt] == -1:
                depth[nxt] = depth[node] + 1
                queue.append(nxt)
    d = max(depth)
    # Choose the first d-1 edges freely; the last edge then fixes the parity.
    return pow(2, d - 1, MOD)

