def ways_to_spell(words, target):
    MOD = 10**9 + 7
    width = len(words[0])
    count = [[0] * 26 for _ in range(width)]  # count[c][letter]
    for w in words:
        for c, ch in enumerate(w):
            count[c][ord(ch) - 97] += 1
    # ways[i] = ways to spell target[:i] using the columns seen so far
    ways = [1] + [0] * len(target)
    for c in range(width):
        for i in range(len(target) - 1, -1, -1):
            ways[i + 1] = (ways[i + 1] + ways[i] * count[c][ord(target[i]) - 97]) % MOD
    return ways[len(target)]

