def palindrome_pairs(words):
    def is_pal(w):
        return w == w[::-1]

    index = {w: i for i, w in enumerate(words)}
    found = set()
    for i, word in enumerate(words):
        for cut in range(len(word) + 1):
            left, right = word[:cut], word[cut:]
            # partner + word: partner is reversed(right), left must be a palindrome
            if is_pal(left):
                j = index.get(right[::-1])
                if j is not None and j != i:
                    found.add((j, i))
            # word + partner: partner is reversed(left), right must be a palindrome
            if is_pal(right):
                j = index.get(left[::-1])
                if j is not None and j != i:
                    found.add((i, j))
    return [list(pair) for pair in sorted(found)]

