def eval_bool(expr):
    stack = []
    for ch in expr:
        if ch == ',' or ch == '(':
            continue
        if ch != ')':
            stack.append(ch)
            continue
        # collect the operands of the operator that this ')' closes
        values = []
        while stack[-1] in 'tf':
            values.append(stack.pop() == 't')
        op = stack.pop()
        if op == '!':
            result = not values[0]
        elif op == '&':
            result = all(values)
        else:
            result = any(values)
        stack.append('t' if result else 'f')
    return stack[0] == 't'

