def divisible_paths(grid, k):
    MOD = 1_000_000_007
    rows, cols = len(grid), len(grid[0])
    # ways[r][c][m] = number of paths to (r, c) whose sum % k == m
    ways = [[[0] * k for _ in range(cols)] for _ in range(rows)]
    ways[0][0][grid[0][0] % k] = 1
    for r in range(rows):
        for c in range(cols):
            for m in range(k):
                count = 0
                if r > 0:
                    count += ways[r - 1][c][m]
                if c > 0:
                    count += ways[r][c - 1][m]
                if count:
                    new_m = (m + grid[r][c]) % k
                    ways[r][c][new_m] = (ways[r][c][new_m] + count) % MOD
    return ways[rows - 1][cols - 1][0]

