from collections import Counter


def reorganize(s):
    counts = Counter(s)

    def can_finish(prev, remaining):
        # Can `remaining` letters be laid out after `prev` with no equal neighbours?
        for ch, c in counts.items():
            limit = remaining // 2 if ch == prev else (remaining + 1) // 2
            if c > limit:
                return False
        return True

    if not can_finish(None, len(s)):
        return ""
    result = []
    prev = None
    for remaining in range(len(s) - 1, -1, -1):
        for ch in sorted(counts):
            if ch == prev or counts[ch] == 0:
                continue
            counts[ch] -= 1
            if can_finish(ch, remaining):
                result.append(ch)
                prev = ch
                break
            counts[ch] += 1
    return "".join(result)

