def reverse_even_groups(head):
    prev_tail = head  # the first group has size 1 and never changes
    planned = 2
    while prev_tail and prev_tail.next:
        # measure the real size of the next group
        size, node = 0, prev_tail.next
        while node and size < planned:
            size += 1
            node = node.next
        if size % 2 == 0:
            # reverse `size` nodes after prev_tail
            first = prev_tail.next
            prev, cur = node, first
            for _ in range(size):
                cur.next, prev, cur = prev, cur, cur.next
            prev_tail.next = prev
            prev_tail = first
        else:
            for _ in range(size):
                prev_tail = prev_tail.next
        planned += 1
    return head

