def surviving_robots(positions, healths, directions):
    health = list(healths)
    order = sorted(range(len(positions)), key=lambda i: positions[i])
    moving_right = []  # robots heading right that haven't met anyone yet
    for i in order:
        if directions[i] == 'R':
            moving_right.append(i)
