def shortest_supersequence(s1, s2):
    n, m = len(s1), len(s2)
    # best[i][j] = length of the shortest supersequence of s1[i:] and s2[j:]
    best = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n, -1, -1):
        for j in range(m, -1, -1):
            if i == n or j == m:
                best[i][j] = (n - i) + (m - j)
            elif s1[i] == s2[j]:
                best[i][j] = best[i + 1][j + 1] + 1
            else:
                best[i][j] = min(best[i + 1][j], best[i][j + 1]) + 1

    out = []
    i = j = 0
    while i < n or j < m:
        choices = []
        for ch in {s1[i] if i < n else None, s2[j] if j < m else None} - {None}:
