    def in_base(x):
        digits = []
        while x:
            digits.append(x % k)
            x //= k
        return digits

    def palindromes():
        length = 1
        while True:
            half = (length + 1) // 2
            for left in range(10 ** (half - 1), 10 ** half):
                text = str(left)
                if length % 2:
                    yield int(text + text[-2::-1])
                else:
                    yield int(text + text[::-1])
            length += 1

    total = 0
    found = 0
    for value in palindromes():
        digits = in_base(value)
        if digits == digits[::-1]:
            total += value
            found += 1
            if found == n:
