from functools import lru_cache
from itertools import product


def earliest_and_latest(n, first, second):
    @lru_cache(maxsize=None)
    def play(size, a, b):
        if a + b == size + 1:
            return (1, 1)
        pairs = [(i, size + 1 - i) for i in range(1, size // 2 + 1)]
        open_pairs = [p for p in pairs if a not in p and b not in p]
        best_early, best_late = size, 0
        for picks in product((0, 1), repeat=len(open_pairs)):
            winners = {a, b}
            if size % 2 == 1:
                winners.add((size + 1) // 2)
            for (x, y), pick in zip(open_pairs, picks):
                winners.add(y if pick else x)
            order = sorted(winners)
            early, late = play(len(order), order.index(a) + 1, order.index(b) + 1)
            best_early = min(best_early, early + 1)
            best_late = max(best_late, late + 1)
        return (best_early, best_late)

    return list(play(n, first, second))

