from functools import lru_cache


def total_waviness(num1, num2):
    def up_to(limit):
        digits = [int(c) for c in str(limit)]

        @lru_cache(maxsize=None)
        def go(pos, before, last, tight, placed):
            # returns (how many numbers complete from here, their total waviness)
            if pos == len(digits):
                return (1, 0)
            top = digits[pos] if tight else 9
            count = total = 0
            for d in range(top + 1):
                next_tight = tight and d == top
                if placed == 0 and d == 0:
                    c, w = go(pos + 1, -1, -1, next_tight, 0)
                    count += c
                    total += w
                    continue
                wave = placed >= 2 and ((last > before and last > d) or (last < before and last < d))
                c, w = go(pos + 1, last, d, next_tight, min(placed + 1, 2))
                count += c
                total += w + (c if wave else 0)
            return (count, total)

        return go(0, -1, -1, True, 0)[1]

    return up_to(num2) - up_to(num1 - 1)

