def farthest_squared(commands, obstacles):
    blocked = {(x, y) for x, y in obstacles}
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    facing = 0
    x = y = 0
    best = 0
    for cmd in commands:
        if cmd == -2:
            facing = (facing + 3) % 4
        elif cmd == -1:
            facing = (facing + 1) % 4
        else:
            dx, dy = directions[facing]
            for _ in range(cmd):
                if (x + dx, y + dy) in blocked:
                    break
                x += dx
                y += dy
            best = max(best, x * x + y * y)
    return best

