def fair_removals(nums):
    right_even = sum(nums[0::2])
    right_odd = sum(nums[1::2])
    left_even = left_odd = 0
    count = 0
    for i, x in enumerate(nums):
        if i % 2 == 0:
            right_even -= x
        else:
            right_odd -= x
        # elements after i switch parity once i is removed
        if left_even + right_odd == left_odd + right_even:
            count += 1
        if i % 2 == 0:
            left_even += x
        else:
            left_odd += x
    return count

