from collections import defaultdict


def shortest_ladders(start, goal, words):
    vocab = set(words)
    if goal not in vocab:
        return []
    parents = defaultdict(list)
    layer = {start}
    found = False
    while layer and not found:
        vocab -= layer
        next_layer = set()
        for word in layer:
            for i in range(len(word)):
                for ch in "abcdefghijklmnopqrstuvwxyz":
                    nxt = word[:i] + ch + word[i + 1:]
                    if nxt in vocab:
                        parents[nxt].append(word)
                        next_layer.add(nxt)
                        if nxt == goal:
                            found = True
        layer = next_layer
    if not found:
        return []

    ladders = []

    def walk_back(word, path):
        if word == start:
            ladders.append(path[::-1])
            return
        for prev in parents[word]:
            walk_back(prev, path + [prev])

    walk_back(goal, [goal])
    return ladders

